import sys, unicodedata, platform, codecs, json
assert sys.version_info[:3] == (3,14,7)
assert unicodedata.unidata_version == '16.0.0'
assert sys.byteorder == 'little'
results=[]
for data in (b'',b'\xef',b'\xef\xbb',b'\xef\xbb\xbfA\xe2\x82\xac',b'\xef\xbb\xbf\xed\xa0\x80',b'\xef\xbb\xbf\xff'):
 for errors in ('strict','replace','ignore','surrogatepass','surrogateescape','backslashreplace'):
  for split in range(len(data)+1):
   decoder=codecs.getincrementaldecoder('utf-8-sig')(errors)
   events=[]
   for chunk,final in ((data[:split],False),(data[split:],True)):
    try: result={'text':list(map(ord,decoder.decode(chunk,final)))}
    except UnicodeDecodeError as error: result={'error':[error.encoding,list(error.object),error.start,error.end,error.reason]}
    state=decoder.getstate()
    events.append({**result,'state':[list(state[0]),state[1]]})
   results.append({'input':list(data),'errors':errors,'split':split,'events':events})
print(json.dumps({'oracle':{'version':sys.version,'unicode':unicodedata.unidata_version,'platform':platform.platform(),'byteorder':sys.byteorder},'rows':results}))

