const controller=new AbortController();let reads=0,writes=0;
const session=new PythonSession({hashSeed:[1n,2n],limits:{maxSteps:1000000,maxAllocatedBytes:16000000,maxDepth:100},signal:controller.signal,
input:{readLine(){let line='';const byte=Buffer.alloc(1);for(;;){reads++;const n=readSync(0,byte,0,1,null);if(n===0)return line===''?null:line;line+=String.fromCharCode(byte[0]);if(byte[0]===10){if(false)controller.abort();return line;}}}},
output:{write(text){const bytes=Buffer.from(text);for(let offset=0;offset<bytes.length;){const n=writeSync(1,bytes,offset,Math.min(3,bytes.length-offset));if(n<=0)throw Error('write failed');offset+=n;writes++;}},flush(){}}
});
const result=session.exec("import codecs
decoder = codecs.getincrementaldecoder('utf-8-sig')('signature-service')
failure = ValueError('callback failed')
retained = []
def handler(error):
    retained.append(error)
    assert input() == 'ready'
    decoder.setstate((b'\xe2\x82', 0))
    raise failure
codecs.register_error('signature-service', handler)
try:
    decoder.decode(b'\xff', True)
except ValueError as error:
    assert error is failure
else:
    assert False
assert decoder.getstate() == (b'\xe2\x82', 0)
assert retained[0].object == b'\xff'
decoder.errors = 'strict'
assert decoder.decode(b'\xac', True) == '\u20ac'
assert decoder.getstate() == (b'', 0)
class Position:
    def __index__(self):
        assert input() == 'resume'
        retained[-1].object = b'XY'
        return -1
def resume(error):
    retained.append(error)
    return ('?', Position())
codecs.register_error('signature-service', resume)
decoder.errors = 'signature-service'
assert decoder.decode(b'\xff', True) == '?Y'
assert retained[-1].args == ('utf-8', b'\xff', 0, 1, 'invalid start byte')
assert decoder.getstate() == (b'', 0)
print('UTF-8-SIG recovery verified')
